using System.Collections.Generic;

namespace Tradewatch
{
    // One exchange's entry in holidays.json (generated by tools/build_holidays.py).
    public class ExchangeCalendar
    {
        // "yyyy-MM-dd" -> holiday name
        public Dictionary<string, string> Holidays { get; set; } = new();
        // "yyyy-MM-dd" -> early closing time, "HH:mm" exchange-local
        public Dictionary<string, string> EarlyCloses { get; set; } = new();
    }
}
